# Reviewed under AGENTS.md
class Money:
    def __init__(self, cents):
        self.cents = cents

    def __add__(self, o):
        if not isinstance(o, Money):
            return NotImplemented
        return Money(self.cents + o.cents)

    def __radd__(self, o):
        if o == 0:
            return self
        return NotImplemented

    def __sub__(self, o):
        if not isinstance(o, Money):
            return NotImplemented
        return Money(self.cents - o.cents)

    def __neg__(self):
        return Money(-self.cents)

    def __eq__(self, o):
        if not isinstance(o, Money):
            return NotImplemented
        return self.cents == o.cents

    def __hash__(self):
        return hash((Money, self.cents))

    def __repr__(self):
        return f'Money({self.cents})'

    def __str__(self):
        sign = '-' if self.cents < 0 else ''
        return f'{sign}${abs(self.cents) / 100:,.2f}'

    def split(self, n):
        if n < 1:
            raise ValueError('cannot split money into fewer than one part')
        share, remainder = divmod(self.cents, n)
        return [Money(share + (1 if i < remainder else 0)) for i in range(n)]
